95	/**
96	 * Resolves the requested model alias (e.g., 'auto-gemini-3', 'pro', 'flash', 'flash-lite')
97	 * to a concrete model name.
98	 *
99	 * @param requestedModel The model alias or concrete model name requested by the user.
100	 * @param useGemini3_1 Whether to use Gemini 3.1 Pro Preview for auto/pro aliases.
101	 * @param hasAccessToPreview Whether the user has access to preview models.
102	 * @returns The resolved concrete model name.
103	 */
104	export function resolveModel(
105	  requestedModel: string,
106	  useGemini3_1: boolean = false,
107	  useGemini3_1FlashLite: boolean = false,
108	  useCustomToolModel: boolean = false,
109	  hasAccessToPreview: boolean = true,
110	  config?: ModelCapabilityContext,
111	): string {
112	  if (config?.getExperimentalDynamicModelConfiguration?.() === true) {
113	    const resolved = config.modelConfigService.resolveModelId(requestedModel, {
114	      useGemini3_1,
115	      useGemini3_1FlashLite,
116	      useCustomTools: useCustomToolModel,
117	      hasAccessToPreview,
118	    });
119	
120	    if (!hasAccessToPreview && isPreviewModel(resolved, config)) {
121	      // Fallback for unknown preview models.
122	      if (resolved.includes('flash-lite')) {
123	        return DEFAULT_GEMINI_FLASH_LITE_MODEL;
124	      }
125	      if (resolved.includes('flash')) {
126	        return DEFAULT_GEMINI_FLASH_MODEL;
127	      }
128	      return DEFAULT_GEMINI_MODEL;
129	    }
130	
131	    return resolved;
132	  }
